// Episode data + shared world positions. Timeline/eventos are generated by tools/maquinista_voz.py and
// tools/maquinista_som.py (voice words, camera keys resolved on words, heartbeats, barks, lever pulls).
import * as THREE from 'three';
import TL from './ep1/timeline.json';
import EV from './ep1/eventos.json';

export type Palavra = {w: string; a: number; b: number; linha: string; quem: string};
export type Chave = {pose: string; t: number; move: 'cut' | 'travel' | 'whip' | 'fly'; dur?: number; roll?: number;
  creep?: number; kick?: number; flash?: number};
export const PALAVRAS = TL.palavras as Palavra[];
export const ROTEIRO = TL as unknown as {titulo: string; trilho_a: string; trilho_b: string; pergunta: string; contagem: number};
export const CHAVES = (EV.keys as Chave[]).slice().sort((a, b) => a.t - b.t);
export const KICKS = EV.kicks as [number, number][];
export const PUXADAS = EV.puxadas as number[];
export const SOLTA = EV.solta as number;
export const BATIDAS = EV.batidas as number[];
export const LATIDOS = EV.latidos as [number, number][];
export const CONTAGEM = EV.contagem as number;
export const DUR = EV.duracao as number;
export const TITULO_ATE = EV.titulo_ate as number;

export const cl = (x: number, a = 0, b = 1) => Math.min(b, Math.max(a, x));
export const smooth = (u: number) => { u = cl(u); return u * u * (3 - 2 * u); };
/** kit ease: soft start, velocity peak at ~40 % of the move, longer settle */
export const ease40 = (u: number) => smooth(Math.pow(cl(u), 0.756));
export const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
export const rng = (seed: number) => () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

/** train front z over time: fast down the hill, still racing in the countdown, 20 m before the fork at the end */
export const ZF = (t: number) => { const r = Math.max(0, DUR - t); return 20 + 12 * r + 0.2 * r * r; };
/** track centre x: main line on z >= 0, branch A (side -1, viewer left) / B (+1) after the fork */
export const ramoX = (lado: number, z: number) => (z >= 0 ? 0 : lado * 4 * smooth(-z / 26));
export const TRILHO_Y = 0.32;  // top of the sleepers: feet of whoever stands on the track

// world spots (people stand on the sleepers of their track)
export const CAIXA = V(-4, TRILHO_Y, -40);
export const HELENA = V(-2.3, TRILHO_Y, -39.6);
export const CIDA = V(4, TRILHO_Y, -40);
export const PANDA = V(4, 1.0, -39.82);
export const FRASCO = V(-2.02, 1.05, -39.4);
export const PLACA_A = V(-8.5, 0, -9);
export const PLACA_B = V(8.5, 0, -9);
// inside the cab (relative to the train front)
export const CAB_Z = 7.6, PISO = 1.55;
export const cabeca = (t: number) => V(0.4, 3.13, ZF(t) + CAB_Z);
export const freio = (t: number) => V(-0.3, 2.42, ZF(t) + 6.1);   // brake knob at rest
export const desvio = (t: number) => V(-1.0, 2.57, ZF(t) + 6.6);  // switch knob

/** words said by a person (mouth open while each word plays) */
export const falando = (quem: string, t: number) => PALAVRAS.some((w) => w.quem === quem && t >= w.a && t < Math.max(w.a + 0.08, w.b - 0.04));
export const palavra = (nome: string, n = 1) => { let k = 0; for (const w of PALAVRAS) if (w.w.replace(/[.,!?;:]/g, '') === nome && ++k === n) return w.a; return -1; };
/** heartbeat envelope 0..1 (sharp hit, fast decay) */
export const pulso = (t: number) => { let e = 0; for (const b of BATIDAS) { if (b > t) break; e = Math.max(e, Math.exp(-(t - b) / 0.11)); } return e; };
